460	//
461	// A configured checkpoint_remote is the authoritative checkpoint store: when one
462	// is set the local ref is only ever sourced from it, never from origin's
463	// (possibly stale) tracking ref (issue #1374). Without a checkpoint_remote,
464	// origin holds the store — when Primary is in Push and the local ref is missing
465	// or un-initialized, the local ref is created/updated from origin's
466	// remote-tracking ref. Otherwise an empty orphan is created.
467	// primaryIsGitRefs reports whether the configured primary checkpoint backend is
468	// git-refs. Resolution is fail-soft: any config-load error is treated as the
469	// default git-branch backend (returns false), preserving legacy behavior.
470	func primaryIsGitRefs(ctx context.Context) bool {
471		cfg, err := settings.LoadCheckpointsConfig(ctx)
472		if err != nil {
473			return false
474		}
475		return checkpoint.PrimaryIsRefs(cfg)
476	}
477	
478	func EnsurePrimaryRef(ctx context.Context, repo *git.Repository) error {
479		// Rebind settings/remote resolution to the repository being modified rather
480		// than the ambient working directory, so the "is a checkpoint_remote
481		// configured" decision (and any fetch below) targets repo even when a caller
482		// passes a handle for a repo that is not CWD. EnsureSetup opens repo from CWD
483		// and tests t.Chdir into it, so in normal use this is a no-op.
484		if root, rootErr := getRepoPath(repo); rootErr == nil {
485			ctx = settings.WithWorktreeRoot(ctx, root)
486		}
487	
488		refs := checkpoint.ResolveRefs(ctx)
489		primaryName := refs.Primary.Short()
490	
491		// Under the git-refs primary backend, checkpoints are written to
492		// per-checkpoint refs and nothing is ever written to the v1 metadata
493		// branch. Seeding an empty orphan v1 here would leave a vestigial,
494		// never-written branch — the surprise a user hit when `entire enable`
495		// selected git-refs yet still created entire/checkpoints/v1. We still adopt
496		// real v1 data that already exists on origin below; we suppress the
497		// empty-orphan fallback and, since there is no orphan that could diverge,
498		// the checkpoint-remote bootstrap fetch too. Legacy checkpoints stay
499		// readable either way — the read path recovers the branch on demand (see
500		// checkpoint.MetadataBranchFetchFunc). Resolution is fail-soft: an
501		// unreadable config keeps the legacy git-branch seeding behavior.
502		skipEmptyOrphan := primaryIsGitRefs(ctx)
503	
504		localRef, localErr := repo.Reference(refs.Primary, true)
505		if localErr != nil && !errors.Is(localErr, plumbing.ErrReferenceNotFound) {
506			return fmt.Errorf("failed to check metadata ref: %w", localErr)
507		}
508		localExists := localErr == nil
509	
510		// A configured checkpoint_remote is the authoritative checkpoint store and
511		// takes precedence over origin's (possibly stale) primary tracking ref. When
512		// it is configured we never seed from origin: a machine migrated from
513		// origin-hosted checkpoints to a dedicated checkpoint_remote must not replay
514		// origin's stale checkpoints into it (issue #1374). The network fetch is
